class TestGetInteriorSlice(unittest.TestCase) :
	'''
	Four cases from the match statement in getInteriorSlice:
	  (0, True)   → slice(1, None)      start of axis, forward
	  (-1, True)  → slice(0, -1)        end of axis, forward
	  (0, False)  → slice(-1, 0, -1)    start of axis, backward
	  (-1, False) → slice(-2, None, -1) end of axis, backward
	'''

	def _axis(self, v0, v1) :
		return HexBlockVertices.AxisProperties(v0, v1)

	def test_invalid_vertex_out_of_range(self) :
		with self.assertRaises(AssertionError) :
			getInteriorSlice(8, self._axis(0, 1))

	def test_invalid_vertex_negative(self) :
		with self.assertRaises(AssertionError) :
			getInteriorSlice(-1, self._axis(0, 1))

	def test_invalid_axis_type(self) :
		with self.assertRaises(AssertionError) :
			getInteriorSlice(0, None)  # type: ignore[arg-type]

	def test_start_forward(self) :
		# v0 along axis-0 +: vertex_map[0][0]=0, orient=True
		self.assertEqual(getInteriorSlice(0, self._axis(0, 1)), slice(1, None))

	def test_end_forward(self) :
		# v1 along axis-0 +: vertex_map[1][0]=-1, orient=True
		self.assertEqual(getInteriorSlice(1, self._axis(0, 1)), slice(0, -1))

	def test_end_backward(self) :
		# v1 along axis-0 reversed: vertex_map[1][0]=-1, orient=False
		# Case (-1, False) → slice(-2, None, -1)
		self.assertEqual(getInteriorSlice(1, self._axis(1, 0)), slice(-2, None, -1))

	def test_start_backward(self) :
		# v0 along axis-0 reversed: vertex_map[0][0]=0, orient=False
		# Case (0, False) → slice(-1, 0, -1)
		self.assertEqual(getInteriorSlice(0, self._axis(1, 0)), slice(-1, 0, -1))


