class TestSingleCell2DGrid_SetCellIDs(unittest.TestCase) :

	def test_fortran_ordering(self) :
		# Fortran order: axis-0 varies fastest
		# arange(0,6).reshape((2,3), order='F') = [[0,2,4],[1,3,5]]
		grid = SingleCell2DGrid(2, 3)
		grid.setCellIDs(start_ID=0)
		expected = np.array([[0, 2, 4], [1, 3, 5]])
		np.testing.assert_array_equal(grid.cell_ID, expected)

	def test_offset(self) :
		grid = SingleCell2DGrid(2, 3)
		grid.setCellIDs(start_ID=10)
		expected = np.array([[10, 12, 14], [11, 13, 15]])
		np.testing.assert_array_equal(grid.cell_ID, expected)

	def test_returns_next_start_ID(self) :
		grid = SingleCell2DGrid(2, 3)
		next_id = grid.setCellIDs(start_ID=5)
		self.assertEqual(next_id, 11)  # 5 + 2*3

	def test_invalid_negative(self) :
		grid = SingleCell2DGrid(2, 3)
		with self.assertRaises(AssertionError) :
			grid.setCellIDs(start_ID=-1)

	def test_invalid_type(self) :
		grid = SingleCell2DGrid(2, 3)
		with self.assertRaises(AssertionError) :
			grid.setCellIDs(start_ID=0.0)  # type: ignore[arg-type]


class TestSingleCell2DGrid_GetFaceShape(unittest.TestCase) :
	'''
	cell_shape = (n0, n1, 1) — the dummy third axis is always size 1.

	Face (0,3,2,1): v0->v1 along axis1, v1->v2 along axis0  → shape (n1, n0)
	Face (0,1,5,4): v0->v1 along axis0, v1->v2 along axis2  → shape (n0,  1)
	Face (0,4,7,3): v0->v1 along axis2, v1->v2 along axis1  → shape ( 1, n1)
	'''

	def setUp(self) :
		self.grid = SingleCell2DGrid(2, 3)

	def test_face_in_plane(self) :
		# Face (0,3,2,1): axes 1 and 0 → shape (n1, n0) = (3, 2)
		shape = self.grid.getFaceShape((0, 3, 2, 1))
		self.assertEqual(shape, (3, 2))

	def test_face_perpendicular_axis1(self) :
		# Face (0,1,5,4): axes 0 and 2 → shape (n0, 1) = (2, 1)
		shape = self.grid.getFaceShape((0, 1, 5, 4))
		self.assertEqual(shape, (2, 1))

	def test_face_perpendicular_axis0(self) :
		# Face (0,4,7,3): axes 2 and 1 → shape (1, n1) = (1, 3)
		shape = self.grid.getFaceShape((0, 4, 7, 3))
		self.assertEqual(shape, (1, 3))


class TestSingleCell2DGrid_GetSetPointIDs(unittest.TestCase) :
	'''
	Grid: SingleCell2DGrid(2, 3) → point_ID shape (2, 3, 2, 2, 2)

	getPointIDs / setPointIDs accept a Slice5D and operate on a view of point_ID.
	'''

	def setUp(self) :
		self.grid = SingleCell2DGrid(2, 3)

	def _corner_slice(self, vi=0, vj=0, vk=0) :
		'''Slice targeting local vertex (vi, vj, vk) for all cells.'''
		s = Slice5D()
		s.slices[2] = vi ; s.slices[3] = vj ; s.slices[4] = vk
		return s

	# ── corner slice (all cells, fixed local vertex) ──────────────────────────

	# ── input validation ──────────────────────────────────────────────────────

	def test_getPointIDs_invalid_slice_type(self) :
		with self.assertRaises(AssertionError) :
			self.grid.getPointIDs(None)  # type: ignore[arg-type]

	def test_setPointIDs_invalid_slice_type(self) :
		with self.assertRaises(AssertionError) :
			self.grid.setPointIDs(None, np.zeros((2, 3), dtype=int))  # type: ignore[arg-type]

	def test_setPointIDs_invalid_array_type(self) :
		with self.assertRaises(AssertionError) :
			self.grid.setPointIDs(self._corner_slice(), [[0, 1, 2], [3, 4, 5]])  # type: ignore[arg-type]

	def test_setPointIDs_invalid_float_dtype(self) :
		with self.assertRaises(AssertionError) :
			self.grid.setPointIDs(self._corner_slice(), np.zeros((2, 3), dtype=float))

	# ── correct behaviour ─────────────────────────────────────────────────────

	def test_set_get_v0_roundtrip(self) :
		s = self._corner_slice(0, 0, 0)
		ids = np.arange(6).reshape(2, 3)
		self.grid.setPointIDs(s, ids)
		np.testing.assert_array_equal(self.grid.getPointIDs(s), ids)

	def test_set_v0_lands_at_correct_array_position(self) :
		s = self._corner_slice(0, 0, 0)
		ids = np.arange(6).reshape(2, 3)
		self.grid.setPointIDs(s, ids)
		np.testing.assert_array_equal(self.grid.point_ID[:, :, 0, 0, 0], ids)

	def test_set_v0_does_not_clobber_v1(self) :
		# v1 local coords are (-1, 0, 0); must stay at sentinel
		s = self._corner_slice(0, 0, 0)
		self.grid.setPointIDs(s, np.arange(6).reshape(2, 3))
		np.testing.assert_array_equal(
			self.grid.point_ID[:, :, -1, 0, 0],
			np.full((2, 3), -1)
		)

	def test_different_local_vertices_independent(self) :
		# Setting v0 corner then v7 corner must not overlap
		s_v0 = self._corner_slice(0, 0, 0)
		s_v7 = self._corner_slice(0, -1, -1)
		self.grid.setPointIDs(s_v0, np.full((2, 3), 10))
		self.grid.setPointIDs(s_v7, np.full((2, 3), 20))
		np.testing.assert_array_equal(self.grid.point_ID[:, :, 0, 0, 0], np.full((2, 3), 10))
		np.testing.assert_array_equal(self.grid.point_ID[:, :, 0, -1, -1], np.full((2, 3), 20))

	# ── getPointIDs returns a writable view ───────────────────────────────────

	def test_get_returns_writable_view(self) :
		s = self._corner_slice(0, 0, 0)
		view = self.grid.getPointIDs(s)
		view[:] = 99
		np.testing.assert_array_equal(self.grid.point_ID[:, :, 0, 0, 0], np.full((2, 3), 99))

	# ── using getInteriorEdgeSlice ─────────────────────────────────────────────

	def test_edge_interior_roundtrip(self) :
		'''
		edge (0→1), v0-corner: interior view = point_ID[1:, :, 0, 0, 0]
		shape (n0-1, n1) = (1, 3) for this grid.
		'''
		axis = HexBlockVertices.AxisProperties(0, 1)
		s = getInteriorEdgeSlice(0, axis)
		ids = np.full((1, 3), 42)
		self.grid.setPointIDs(s, ids)
		np.testing.assert_array_equal(self.grid.getPointIDs(s), ids)

	def test_edge_interior_positions(self) :
		# edge (0→1) interior at v0-corner only touches row index 1
		axis = HexBlockVertices.AxisProperties(0, 1)
		s = getInteriorEdgeSlice(0, axis)
		self.grid.setPointIDs(s, np.full((1, 3), 42))
		np.testing.assert_array_equal(self.grid.point_ID[1, :, 0, 0, 0], [42, 42, 42])
		np.testing.assert_array_equal(self.grid.point_ID[0, :, 0, 0, 0], [-1, -1, -1])

	def test_two_vertex_edge_slices_independent(self) :
		'''
		Edge (0→1) gives interior slices at two different local vertex positions:
		  v0-corner: point_ID[1:, :, 0, 0, 0]   shape (1, 3)
		  v1-corner: point_ID[:-1, :, -1, 0, 0]  shape (1, 3)
		Setting each independently must not clobber the other.
		'''
		axis = HexBlockVertices.AxisProperties(0, 1)
		s_v0 = getInteriorEdgeSlice(0, axis)
		s_v1 = getInteriorEdgeSlice(1, axis)
		self.grid.setPointIDs(s_v0, np.full((1, 3), 10))
		self.grid.setPointIDs(s_v1, np.full((1, 3), 20))
		# v0-corner at row 1 unchanged by v1 write
		np.testing.assert_array_equal(self.grid.point_ID[1, :, 0, 0, 0], [10, 10, 10])
		# v1-corner at row 0
		np.testing.assert_array_equal(self.grid.point_ID[0, :, -1, 0, 0], [20, 20, 20])
		# v0-corner at row 0 untouched (sentinel)
		np.testing.assert_array_equal(self.grid.point_ID[0, :, 0, 0, 0], [-1, -1, -1])
		# v1-corner at row 1 untouched (sentinel)
		np.testing.assert_array_equal(self.grid.point_ID[1, :, -1, 0, 0], [-1, -1, -1])


